use std::{
    path::{Path, PathBuf},
    sync::OnceLock,
};

use serde_json::Value;

/// Deployment configuration, generated by Nix at `/etc/maia/config.json`.
pub const DEPLOYMENT_CONFIG: &str = "/etc/maia/config.json";

/// Per-user configuration the desktop Settings form owns. Disjoint from the
/// deployment keys, so merging the two is unambiguous.
pub fn overlay_config_path() -> PathBuf {
    let base = std::env::var("XDG_CONFIG_HOME")
        .ok()
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
        // XDG_CONFIG_HOME is unset more often than it is set, and a relative
        // value is not meaningful here.
        .unwrap_or_else(|| match std::env::var("HOME") {
            Ok(home) if !home.is_empty() => PathBuf::from(home).join(".config"),
            _ => PathBuf::from(".config"),
        });
    base.join("maia").join("config.json")
}

/// Configuration file used when nothing else applies: the checkout's `maia.json`,
/// which is what `cargo tauri dev` and a bare `sync-server serve` rely on.
pub const CHECKOUT_CONFIG: &str = "maia.json";

/// The port the API listens on unless configured otherwise.
///
/// Kept in one place because the desktop app, the server and the NixOS module
/// all need to agree on it, and a mismatch is otherwise only visible as a
/// connection failure on the phone.
pub const DEFAULT_PORT: u16 = 3030;

#[derive(Clone, Debug)]
pub struct Config {
    pub bind_addr: String,
    pub db_path: PathBuf,
    pub api_key: String,
    /// Key for the vision model used to parse receipt images. Empty means OCR is
    /// not configured: image uploads still succeed, but the parse endpoints
    /// report `503` instead of calling the model.
    pub model_api_key: String,
    /// Vision model id, e.g. `gemini-2.5-flash`.
    pub model_name: String,
    /// Where exercise images and videos are read from, serving `GET /media/*`.
    ///
    /// `None` falls back to `<db_dir>/exercise_media`, which is what a checkout
    /// with the database beside the media wants.
    pub media_dir: Option<PathBuf>,
    /// Where the exercise catalogue is seeded from on first boot, looked for as
    /// `<dir>/parsed`. `None` disables seeding.
    ///
    /// Separate from [`Config::media_dir`] because seeding reads from the
    /// checkout while media is served from wherever the deployment put it.
    pub seed_dir: Option<PathBuf>,
    /// Where the desktop app writes markdown notes.
    pub notes_dir: Option<PathBuf>,
}

impl Config {
    pub fn new(db_path: PathBuf, api_key: String) -> Self {
        Self {
            bind_addr: format!("0.0.0.0:{DEFAULT_PORT}"),
            db_path,
            api_key,
            model_api_key: String::new(),
            model_name: "gemini-2.5-flash".to_string(),
            media_dir: None,
            seed_dir: None,
            notes_dir: None,
        }
    }

    pub fn with_bind_addr(mut self, addr: impl Into<String>) -> Self {
        self.bind_addr = addr.into();
        self
    }

    /// Enables receipt OCR. An empty [key] leaves OCR unconfigured.
    pub fn with_model(mut self, key: impl Into<String>, name: impl Into<String>) -> Self {
        self.model_api_key = key.into().trim().to_string();
        self.model_name = name.into();
        self
    }

    pub fn with_media_dir(mut self, dir: Option<PathBuf>) -> Self {
        self.media_dir = dir;
        self
    }

    pub fn with_seed_dir(mut self, dir: Option<PathBuf>) -> Self {
        self.seed_dir = dir;
        self
    }

    /// True when a model key was supplied, i.e. receipt OCR can run.
    pub fn ocr_enabled(&self) -> bool {
        !self.model_api_key.is_empty()
    }

    /// Directory holding exercise images and videos for `GET /media/*`.
    ///
    /// Defaults to `<db_dir>/exercise_media`.
    pub fn media_dir(&self) -> PathBuf {
        self.media_dir.clone().unwrap_or_else(|| {
            self.db_path
                .parent()
                .unwrap_or_else(|| Path::new("."))
                .join("exercise_media")
        })
    }

    /// The port parsed out of `bind_addr`.
    pub fn port(&self) -> u16 {
        self.bind_addr
            .rsplit(':')
            .next()
            .and_then(|p| p.trim().parse().ok())
            .unwrap_or(DEFAULT_PORT)
    }

    /// Reads the deployment file named by [explicit], else `/etc/maia/config.json`,
    /// else the checkout's `maia.json`, then merges the per-user overlay on top.
    ///
    /// A missing file is not an error: a fresh checkout has neither, and the
    /// defaults below suit it. A malformed file *is* an error, because silently
    /// falling back to a default database or a default API key would be worse.
    pub fn load(explicit: Option<&Path>) -> anyhow::Result<Self> {
        let deployment = match explicit {
            Some(path) => Some(path.to_path_buf()),
            None => [DEPLOYMENT_CONFIG, CHECKOUT_CONFIG]
                .into_iter()
                .map(PathBuf::from)
                .find(|p| p.exists()),
        };
        let merged = match deployment {
            Some(path) => read_object(&path)?,
            None => serde_json::Map::new(),
        };
        // Best effort: the overlay is optional, and its absence is normal for a
        // server that has no desktop half.
        let overlay = read_object(&overlay_config_path()).unwrap_or_default();
        Ok(Self::from_values(merged, overlay))
    }

    /// Process-wide configuration, loaded once.
    ///
    /// Both the server binary and the desktop app need it before any command can
    /// run, and re-reading on each call would make a partial write show up as
    /// inconsistent behaviour within a single request.
    pub fn shared(explicit: Option<&Path>) -> anyhow::Result<&'static Self> {
        static CACHE: OnceLock<anyhow::Result<Config>> = OnceLock::new();
        CACHE
            .get_or_init(|| Self::load(explicit.map(Path::new)))
            .as_ref()
            .map_err(|e| anyhow::anyhow!("{e}"))
    }

    /// Builds a configuration from a deployment object plus a desktop overlay.
    ///
    /// Split out from [`Config::load`] so the precedence rules can be tested
    /// without touching the filesystem.
    pub fn from_values(deployment: serde_json::Map<String, Value>, overlay: serde_json::Map<String, Value>) -> Self {
        let get = |map: &serde_json::Map<String, Value>, key: &str| -> Option<String> {
            map.get(key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|v| !v.is_empty())
                .map(str::to_owned)
        };

        let db_path = get(&deployment, "database")
            .or_else(|| get(&overlay, "database"))
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("maia.db"));

        let mut cfg = Self::new(
            db_path,
            get(&deployment, "api_key").unwrap_or_else(|| "fitfat-sync-key".into()),
        );

        if let Some(addr) = get(&deployment, "bind_addr") {
            cfg = cfg.with_bind_addr(addr);
        }
        if let Some(name) = get(&deployment, "model_name") {
            cfg = cfg.with_model(
                get(&deployment, "model_api").unwrap_or_default(),
                name,
            );
        } else if let Some(key) = get(&deployment, "model_api") {
            let name = cfg.model_name.clone();
            cfg = cfg.with_model(key, name);
        }

        cfg.media_dir = get(&deployment, "media_dir").map(PathBuf::from);
        cfg.seed_dir = get(&deployment, "seed_dir").map(PathBuf::from);
        cfg.notes_dir = get(&deployment, "notes_dir")
            .or_else(|| get(&overlay, "notes_dir"))
            .map(PathBuf::from);
        cfg
    }
}

/// Reads a JSON object from [path], treating "does not exist" as absent.
///
/// A parse failure is surfaced: a config file with a typo in it should stop the
/// service, not leave it listening with a default API key.
fn read_object(path: &Path) -> anyhow::Result<serde_json::Map<String, Value>> {
    let text = match std::fs::read_to_string(path) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(serde_json::Map::new()),
        Err(e) => return Err(anyhow::anyhow!("reading {}: {e}", path.display())),
    };
    if text.trim().is_empty() {
        return Ok(serde_json::Map::new());
    }
    let value: Value = serde_json::from_str(&text)
        .map_err(|e| anyhow::anyhow!("parsing {}: {e}", path.display()))?;
    match value {
        Value::Object(map) => Ok(map),
        other => Err(anyhow::anyhow!(
            "{} must contain a JSON object, found {}",
            path.display(),
            kind_of(&other)
        )),
    }
}

fn kind_of(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
        Value::String(_) => "a string",
        Value::Array(_) => "an array",
        Value::Object(_) => "an object",
    }
}

impl Default for Config {
    /// An in-memory database on an ephemeral port, for tests.
    fn default() -> Self {
        Self {
            bind_addr: "0.0.0.0:0".to_string(),
            db_path: PathBuf::from(":memory:"),
            api_key: "test-key".to_string(),
            model_api_key: String::new(),
            model_name: "gemini-2.5-flash".to_string(),
            media_dir: None,
            seed_dir: None,
            notes_dir: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn obj(value: Value) -> serde_json::Map<String, Value> {
        value.as_object().unwrap().clone()
    }

    #[test]
    fn empty_input_yields_checkout_defaults() {
        let cfg = Config::from_values(serde_json::Map::new(), serde_json::Map::new());
        assert_eq!(cfg.db_path, PathBuf::from("maia.db"));
        assert_eq!(cfg.bind_addr, "0.0.0.0:3030");
        assert_eq!(cfg.api_key, "fitfat-sync-key");
        assert_eq!(cfg.media_dir(), PathBuf::from("exercise_media"));
        assert!(cfg.notes_dir.is_none());
        assert!(!cfg.ocr_enabled());
    }

    #[test]
    fn deployment_keys_are_all_honoured() {
        let cfg = Config::from_values(
            obj(json!({
                "database": "/var/lib/maia/maia.db",
                "bind_addr": "0.0.0.0:8080",
                "media_dir": "/srv/media",
                "seed_dir": "/srv/data",
                "notes_dir": "/var/lib/maia/notes",
                "api_key": "from-file",
                "model_api": "  gemini-key  ",
                "model_name": "gemini-2.5-pro",
            })),
            serde_json::Map::new(),
        );
        assert_eq!(cfg.db_path, PathBuf::from("/var/lib/maia/maia.db"));
        assert_eq!(cfg.port(), 8080);
        assert_eq!(cfg.api_key, "from-file");
        assert_eq!(cfg.media_dir(), PathBuf::from("/srv/media"));
        assert_eq!(cfg.seed_dir, Some(PathBuf::from("/srv/data")));
        assert_eq!(cfg.notes_dir, Some(PathBuf::from("/var/lib/maia/notes")));
        assert_eq!(cfg.model_api_key, "gemini-key");
        assert_eq!(cfg.model_name, "gemini-2.5-pro");
        assert!(cfg.ocr_enabled());
    }

    #[test]
    fn overlay_cannot_override_deployment_keys() {
        // The overlay only owns desktop paths; it must not be able to redirect
        // the database or replace the API key.
        let cfg = Config::from_values(
            obj(json!({ "database": "/var/lib/maia/maia.db", "api_key": "real" })),
            obj(json!({
                "database": "/tmp/hijacked.db",
                "api_key": "stolen",
                "receipts_path": "/home/lucas/receipts",
                "nutriments_path": "/home/lucas/nutriments",
            })),
        );
        assert_eq!(cfg.db_path, PathBuf::from("/var/lib/maia/maia.db"));
        assert_eq!(cfg.api_key, "real");
    }

    #[test]
    fn blank_strings_fall_through_to_defaults() {
        let cfg = Config::from_values(
            obj(json!({
                "database": "",
                "api_key": "   ",
                "media_dir": "",
                "bind_addr": "",
            })),
            serde_json::Map::new(),
        );
        assert_eq!(cfg.db_path, PathBuf::from("maia.db"));
        assert_eq!(cfg.api_key, "fitfat-sync-key");
        assert_eq!(cfg.media_dir, None);
        assert_eq!(cfg.bind_addr, "0.0.0.0:3030");
    }

    #[test]
    fn model_name_without_a_key_leaves_ocr_disabled() {
        let cfg = Config::from_values(
            obj(json!({ "model_name": "gemini-2.5-pro" })),
            serde_json::Map::new(),
        );
        assert_eq!(cfg.model_name, "gemini-2.5-pro");
        assert!(
            !cfg.ocr_enabled(),
            "without a key OCR must stay off rather than always fail"
        );
    }

    #[test]
    fn malformed_config_is_an_error() {
        let dir = std::env::temp_dir().join(format!("maia-cfg-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("config.json");
        std::fs::write(&path, "{ not json").unwrap();
        let err = read_object(&path).unwrap_err().to_string();
        assert!(err.contains("parsing"), "unhelpful error: {err}");

        // A JSON array is valid JSON but not a usable config.
        std::fs::write(&path, "[]").unwrap();
        let err = read_object(&path).unwrap_err().to_string();
        assert!(err.contains("must contain a JSON object"), "got: {err}");

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn missing_file_is_absent_not_an_error() {
        let path = std::path::Path::new("/nonexistent/maia/config.json");
        assert!(read_object(path).unwrap().is_empty());
    }

    #[test]
    fn port_parsing_survives_odd_bind_addrs() {
        let base = Config::new(PathBuf::from("x"), "k".into());
        assert_eq!(base.port(), DEFAULT_PORT);
        assert_eq!(base.clone().with_bind_addr("[::]:9999").port(), 9999);
        // Unparseable input falls back rather than panicking at startup.
        assert_eq!(base.with_bind_addr("nonsense").port(), DEFAULT_PORT);
    }
}